package pe.nexo.store.auth;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.Map;
@RestController@RequestMapping("/api/auth")public class AuthController{private final TokenService tokens;private final PasswordEncoder encoder;private final String email;private final String passwordHash;public AuthController(TokenService tokens,PasswordEncoder encoder,@Value("${app.admin.email}")String email,@Value("${app.admin.password}")String password){this.tokens=tokens;this.encoder=encoder;this.email=email;this.passwordHash=encoder.encode(password);}public record LoginRequest(@Email@NotBlank String email,@NotBlank String password){}private Map<String,String>user(){return Map.of("name","Junior Admin","email",email,"role","ADMIN");}@PostMapping("/login")public Map<String,Object>login(@Valid@RequestBody LoginRequest r){if(!email.equalsIgnoreCase(r.email())||!encoder.matches(r.password(),passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credenciales incorrectas");return Map.of("token",tokens.create(email),"user",user());}@GetMapping("/me")public Map<String,String>me(){return user();}}
